begin;
create temporary sequence csa164_assertion;
create function pg_temp.assert_ok(c boolean,d text) returns text language plpgsql as $$begin if c is distinct from true then raise exception 'Assertion failed: %',d;end if;return 'ok '||nextval('pg_temp.csa164_assertion')||' - '||d;end;$$;
create function pg_temp.expect_error(q text,s text,d text) returns text language plpgsql as $$declare actual text;begin begin execute q;exception when others then actual:=sqlstate;end;return pg_temp.assert_ok(actual=s,d);end;$$;
insert into auth.users(id) values('16400000-0000-0000-0000-000000000001'),('16400000-0000-0000-0000-000000000002');
insert into public.profiles(id,display_name) select id,'Synthetic' from auth.users where id::text like '164%' on conflict do nothing;
insert into auth.sessions(id,user_id,aal,not_after) values('16400000-0000-0000-0000-000000000011','16400000-0000-0000-0000-000000000001','aal1',now()+interval '1 day'),('16400000-0000-0000-0000-000000000012','16400000-0000-0000-0000-000000000002','aal1',now()+interval '1 day');
insert into public.user_roles(user_id,role_id) select '16400000-0000-0000-0000-000000000001',id from public.roles where code='content_manager';
insert into public.courses(id,slug,title,price_minor) values('16400000-0000-0000-0000-000000000003','synthetic-csa164','Synthetic',0);
insert into public.course_staff(course_id,user_id,staff_role) values('16400000-0000-0000-0000-000000000003','16400000-0000-0000-0000-000000000001','owner');
insert into public.course_sections(id,course_id,title,position) values('16400000-0000-0000-0000-000000000004','16400000-0000-0000-0000-000000000003','Synthetic',0);
insert into public.lessons(id,section_id,title,lesson_type,position) values('16400000-0000-0000-0000-000000000005','16400000-0000-0000-0000-000000000004','Synthetic','pdf',0);
create temporary table reservation as select public.csa164_prepare_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1','16400000-0000-0000-0000-000000000006','16400000-0000-0000-0000-000000000003','16400000-0000-0000-0000-000000000005','course_pdf','application/pdf',9,'synthetic-policy') as data;
select pg_temp.assert_ok((select data->>'bucket'='course-pdfs' and data->>'path'='originals/'||(data->>'asset_id')||'/v1.pdf' and (data->>'validated')::boolean=false from reservation),'private pending reservation');
select pg_temp.assert_ok((select validation_status='pending' and checksum_sha256 is null from app_private.media_assets where id=(select (data->>'asset_id')::uuid from reservation)),'reservation never grants readiness');
select pg_temp.assert_ok((public.csa164_prepare_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1','16400000-0000-0000-0000-000000000006','16400000-0000-0000-0000-000000000003','16400000-0000-0000-0000-000000000005','course_pdf','application/pdf',9,'synthetic-policy')->>'asset_id')=(select data->>'asset_id' from reservation),'identical replay preserves path');
select pg_temp.expect_error($q$select public.csa164_prepare_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1','16400000-0000-0000-0000-000000000006','16400000-0000-0000-0000-000000000003','16400000-0000-0000-0000-000000000005','course_pdf','application/pdf',10,'synthetic-policy')$q$,'22023','conflicting replay denied');
select pg_temp.expect_error(format($q$select public.csa164_get_media_upload('16400000-0000-0000-0000-000000000002','16400000-0000-0000-0000-000000000012','aal1',%L)$q$,(select data->>'asset_id' from reservation)),'42501','student denied asset metadata');
update public.course_staff set revoked_at=clock_timestamp() where user_id='16400000-0000-0000-0000-000000000001';
select pg_temp.expect_error(format($q$select public.csa164_finalize_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1',%L,%L,9,'application/pdf','synthetic-policy')$q$,(select data->>'asset_id' from reservation),repeat('a',64)),'42501','revoked assignment denies finalization');
update public.course_staff set revoked_at=null where user_id='16400000-0000-0000-0000-000000000001';
create function pg_temp.fail_audit() returns trigger language plpgsql as $$begin raise exception 'Injected audit failure';end;$$;
create trigger csa164_test_failure before insert on app_private.csa164_media_validation_audit for each row execute function pg_temp.fail_audit();
select pg_temp.expect_error(format($q$select public.csa164_finalize_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1',%L,%L,9,'application/pdf','synthetic-policy')$q$,(select data->>'asset_id' from reservation),repeat('a',64)),'P0001','audit failure aborts mutation');
select pg_temp.assert_ok((select validation_status='pending' from app_private.media_assets where id=(select (data->>'asset_id')::uuid from reservation)) and not exists(select 1 from app_private.lesson_assets where lesson_id='16400000-0000-0000-0000-000000000005'),'readiness and association roll back');
drop trigger csa164_test_failure on app_private.csa164_media_validation_audit;
select pg_temp.assert_ok((public.csa164_finalize_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1',(select (data->>'asset_id')::uuid from reservation),repeat('a',64),9,'application/pdf','synthetic-policy')->>'status')='validated','trusted validation commits');
select pg_temp.assert_ok((public.csa164_finalize_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1',(select (data->>'asset_id')::uuid from reservation),repeat('a',64),9,'application/pdf','synthetic-policy')->>'replayed')::boolean,'validation replay idempotent');
select pg_temp.assert_ok((select count(*)=1 from app_private.lesson_assets where lesson_id='16400000-0000-0000-0000-000000000005'),'no duplicate association');
select pg_temp.expect_error('delete from app_private.csa164_media_validation_audit','42501','audit immutable');
select pg_temp.assert_ok(not has_function_privilege(r,'public.csa164_finalize_media_upload(uuid,uuid,text,uuid,text,bigint,text,text)','EXECUTE'),'direct client finalization denied '||r) from unnest(array['anon','authenticated']) roles(r);
select pg_temp.assert_ok(not has_table_privilege(r,'app_private.csa164_media_uploads','SELECT'),'private reservations '||r) from unnest(array['anon','authenticated','service_role']) roles(r);
select pg_temp.expect_error(format($q$select public.csa164_finalize_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1',%L,%L,9,'application/pdf','synthetic-policy')$q$,(select data->>'asset_id' from reservation),repeat('b',64)),'22023','different bytes cannot replay validation');
create temporary table second_reservation as select public.csa164_prepare_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1','16400000-0000-0000-0000-000000000098','16400000-0000-0000-0000-000000000003','16400000-0000-0000-0000-000000000005','course_pdf','application/pdf',9,'synthetic-policy') as data;
select pg_temp.expect_error(format($q$select public.csa164_finalize_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1',%L,%L,9,'application/pdf','synthetic-policy')$q$,(select data->>'asset_id' from second_reservation),repeat('b',64)),'22023','second PDF source cannot make accepted resolver ambiguous');
select pg_temp.assert_ok((select count(*)=1 from app_private.lesson_assets where lesson_id='16400000-0000-0000-0000-000000000005') and (select media_asset_id=(select (data->>'asset_id')::uuid from reservation) from app_private.lesson_assets where lesson_id='16400000-0000-0000-0000-000000000005') and (select validation_status='pending' from app_private.media_assets where id=(select (data->>'asset_id')::uuid from second_reservation)),'PDF replacement denial preserves original source and leaves replacement pending');
update auth.sessions set not_after=now()-interval '1 second' where id='16400000-0000-0000-0000-000000000011';
select pg_temp.expect_error(format($q$select public.csa164_get_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1',%L)$q$,(select data->>'asset_id' from reservation)),'42501','expired session cannot read ready asset');
update auth.sessions set not_after=now()+interval '1 day' where id='16400000-0000-0000-0000-000000000011';
update public.user_roles set revoked_at=clock_timestamp() where user_id='16400000-0000-0000-0000-000000000001';
select pg_temp.expect_error(format($q$select public.csa164_get_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1',%L)$q$,(select data->>'asset_id' from reservation)),'42501','revoked role cannot replay ready asset');
update public.user_roles set revoked_at=null where user_id='16400000-0000-0000-0000-000000000001';
select pg_temp.expect_error($q$select public.csa164_prepare_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1','16400000-0000-0000-0000-000000000099','16400000-0000-0000-0000-000000000003','16400000-0000-0000-0000-000000000005','course_pdf','application/pdf',52428801,'synthetic-policy')$q$,'22023','SQL rejects PDF above accepted 50MiB hard cap');
select pg_temp.assert_ok((select app_private.csa139_pdf_path_valid(object_path) and bucket_name='course-pdfs' and object_path='originals/'||id::text||'/v'||content_version::text||'.pdf' and size_bytes between 1 and 52428800 from app_private.media_assets where id=(select (data->>'asset_id')::uuid from reservation)),'validated PDF identity matches accepted delivery resolver');
update storage.buckets set public=true where id='course-media';
select pg_temp.expect_error(format($q$select public.csa164_get_media_upload('16400000-0000-0000-0000-000000000001','16400000-0000-0000-0000-000000000011','aal1',%L)$q$,(select data->>'asset_id' from reservation)),'42501','public bucket configuration fails closed');
select '1..'||last_value from pg_temp.csa164_assertion;
rollback;
